const $=selector=>document.querySelector(selector);
const $$=selector=>[...document.querySelectorAll(selector)];
const STORAGE_PROJECT="schola-fokus-author-project-v1";
const STORAGE_PROJECTS="schola-fokus-author-projects-v2";
const STORAGE_SESSION="schola-fokus-student-session-v1";
const alphabet="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
const uid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const initialProject=()=>({type:"schola-fokus-author",version:1,id:uid(),title:"Neuer Aufgabenspace",intro:"Lies alle Aufgaben aufmerksam. Die Bearbeitungszeit beginnt erst, wenn du auf „Bearbeitung starten“ klickst.",unlockCode:makeCode(4),codes:[],classes:[],tasks:[{id:uid(),type:"text",title:"Aufgabe 1",instructions:"Formuliere deine Antwort im Textfeld.",be:5,wordLimit:0}]});
const legacyProject=load(STORAGE_PROJECT);
const storedLibrary=load(STORAGE_PROJECTS);
let projects=Array.isArray(storedLibrary?.projects)&&storedLibrary.projects.length?storedLibrary.projects:[legacyProject||initialProject()];
let project=projects.find(entry=>entry.id===storedLibrary?.activeProjectId)||projects[0];
let activeTaskId=project.tasks[0]?.id;
let teacherWorkspaceMode="editor";
const expandedFocusProjectIds=new Set();
const expandedFocusClassLayerIds=new Set();
const expandedFocusClassIds=new Set();
let activeFocusBrowserNode={type:"project",projectId:project.id,classId:null};
let studentPackage=null;
let teacherPreviewMode=false;
let session=load(STORAGE_SESSION);
let clockTimer=null,warningTimer=null,lostFocusAt=null;

function load(key){try{return JSON.parse(localStorage.getItem(key))}catch{return null}}
function persistProject(){localStorage.setItem(STORAGE_PROJECTS,JSON.stringify({version:2,activeProjectId:project.id,projects}));localStorage.setItem(STORAGE_PROJECT,JSON.stringify(project));showSave();renderTeacherNav();renderProjectBrowser()}
function persistSession(){if(session)localStorage.setItem(STORAGE_SESSION,JSON.stringify(session))}
function showSave(){const e=$("#saveStatus");e.textContent="Lokal gespeichert";e.animate([{opacity:.35},{opacity:1}],{duration:350})}
function makeCode(length=4){let value="";for(let i=0;i<length;i++)value+=alphabet[crypto.getRandomValues(new Uint8Array(1))[0]%alphabet.length];return value}
function normalizeCode(value){return String(value||"").toUpperCase().replace(/[^A-Z0-9]/g,"")}
async function digest(value){const bytes=new TextEncoder().encode(normalizeCode(value));const hash=await crypto.subtle.digest("SHA-256",bytes);return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,"0")).join("")}
function escapeHtml(value){return String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]))}
function download(name,payload){const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function slug(value){return String(value||"fokus").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")||"fokus"}
function filenamePart(value){return String(value||"Fokus").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[<>:"/\\|?*\x00-\x1F]/g,"").trim().replace(/\s+/g,"_")||"Fokus"}
function filenameTimestamp(date=new Date()){const pad=value=>String(value).padStart(2,"0");return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}_${pad(date.getHours())}-${pad(date.getMinutes())}-${pad(date.getSeconds())}`}
function toast(text){const e=$("#toast");e.textContent=text;e.hidden=false;clearTimeout(e._timer);e._timer=setTimeout(()=>e.hidden=true,2600)}

function setMode(mode){const teacher=mode==="teacher";$("#studentView").hidden=teacher;$$('[data-mode]').forEach(b=>b.classList.toggle("is-active",b.dataset.mode===mode));if(teacher)setTeacherWorkspace(teacherWorkspaceMode);else{document.body.classList.remove("workspace-browser");$("#teacherWorkspaceSwitch").hidden=true;$("#teacherView").hidden=true;$("#projectBrowserView").hidden=true}if(!teacher&&session?.package){studentPackage=session.package;renderStudentPackage();if(session.state==="active"||session.state==="locked")resumeSession()}}
$$('[data-mode]').forEach(button=>button.addEventListener("click",()=>setMode(button.dataset.mode)));

function setTeacherWorkspace(mode){teacherWorkspaceMode=mode==="browser"?"browser":"editor";const browserMode=teacherWorkspaceMode==="browser";document.body.classList.toggle("workspace-browser",browserMode);$("#teacherView").hidden=browserMode;$("#projectBrowserView").hidden=!browserMode;$("#teacherWorkspaceSwitch").hidden=browserMode;if(browserMode)renderProjectBrowser()}
$("#teacherWorkspaceSwitch").onclick=()=>setTeacherWorkspace(teacherWorkspaceMode==="editor"?"browser":"editor");
$("#returnFocusEditor").onclick=()=>setTeacherWorkspace("editor");

function loadProjectIntoEditor(nextProject){project=nextProject;activeTaskId=project.tasks[0]?.id;$("#projectTitle").value=project.title;$("#projectIntro").value=project.intro;persistProject();renderTaskEditor();setTeacherWorkspace("editor")}

function renderTeacherNav(){const nav=$("#taskNavigation");nav.innerHTML=project.tasks.map((task,index)=>`<button class="task-nav-item ${task.id===activeTaskId?"is-active":""}" data-task="${task.id}"><i>${index+1}</i><span>${escapeHtml(task.title||`Aufgabe ${index+1}`)}</span><small>${Number(task.be)||0} BE</small></button>`).join("");nav.querySelectorAll("button").forEach(b=>b.onclick=()=>{activeTaskId=b.dataset.task;renderTeacherNav();renderTaskEditor()});$("#totalBe").textContent=project.tasks.reduce((sum,t)=>sum+(Number(t.be)||0),0)}
function renderTaskEditor(){let task=project.tasks.find(t=>t.id===activeTaskId);if(!task&&project.tasks.length){activeTaskId=project.tasks[0].id;task=project.tasks[0]}const host=$("#taskEditor");if(!task){host.innerHTML='<div class="task-card">Füge einen Aufgabenbereich hinzu.</div>';return}const index=project.tasks.indexOf(task);host.innerHTML=`<article class="task-card"><div class="task-head"><span class="task-number">${index+1}</span><input class="task-title" data-field="title" value="${escapeHtml(task.title)}" aria-label="Aufgabentitel"><label class="field-label be-field">Bewertung<input data-field="be" type="number" min="0" step="0.5" value="${task.be}"></label></div><textarea data-field="instructions" placeholder="Erklärung und Arbeitsauftrag">${escapeHtml(task.instructions)}</textarea><div class="field-config"><label class="field-label">Editorfeld<span>Freies, automatisch wachsendes Textfeld</span></label><label class="field-label">Wortgrenze<input data-field="wordLimit" type="number" min="0" value="${task.wordLimit||0}"></label><button id="removeTask" class="danger-link" type="button">Bereich löschen</button></div></article>`;host.querySelectorAll("[data-field]").forEach(input=>input.addEventListener("input",()=>{task[input.dataset.field]=input.type==="number"?Math.max(0,Number(input.value)||0):input.value;persistProject()}));$("#removeTask").onclick=()=>{if(project.tasks.length===1){toast("Mindestens ein Aufgabenbereich bleibt erhalten.");return}project.tasks=project.tasks.filter(t=>t.id!==task.id);activeTaskId=project.tasks[Math.max(0,index-1)].id;persistProject();renderTaskEditor()}}
$("#projectTitle").value=project.title;$("#projectIntro").value=project.intro;
$("#projectTitle").oninput=e=>{project.title=e.target.value;persistProject()};$("#projectIntro").oninput=e=>{project.intro=e.target.value;persistProject()};
$("#addTask").onclick=()=>$("#taskTypeDialog").showModal();
$("#createTextTask").onclick=()=>{const task={id:uid(),type:"text",title:`Aufgabe ${project.tasks.length+1}`,instructions:"",be:5,wordLimit:0};project.tasks.push(task);activeTaskId=task.id;persistProject();renderTaskEditor();$("#taskTypeDialog").close()};
$("#createClozeTask").onclick=()=>{const task={id:uid(),type:"cloze",title:`Lückentext ${project.tasks.length+1}`,instructions:"Vervollständige den Lückentext.",be:5,clozeText:"Die [[Erde]] bewegt sich um die [[Sonne]].",wordBankEnabled:false,wordBankExtras:""};project.tasks.push(task);activeTaskId=task.id;persistProject();renderTaskEditor();$("#taskTypeDialog").close()};
function parseClozeText(value){const source=String(value||""),parts=[],pattern=/\[\[([\s\S]*?)\]\]/g;let cursor=0,match;while((match=pattern.exec(source))){if(match.index>cursor)parts.push({type:"text",text:source.slice(cursor,match.index)});parts.push({type:"gap",solutions:match[1].split("|").map(item=>item.trim()).filter(Boolean)});cursor=pattern.lastIndex}if(cursor<source.length)parts.push({type:"text",text:source.slice(cursor)});return parts}
const renderTextTaskEditor=renderTaskEditor;
renderTaskEditor=function(){const task=project.tasks.find(entry=>entry.id===activeTaskId);if(!task||task.type!=="cloze"){renderTextTaskEditor();return}const index=project.tasks.indexOf(task),host=$("#taskEditor");host.innerHTML=`<article class="task-card"><div class="task-head"><span class="task-number">${index+1}</span><input class="task-title" data-cloze-field="title" value="${escapeHtml(task.title)}" aria-label="Aufgabentitel"><label class="field-label be-field">Bewertung<input data-cloze-field="be" type="number" min="0" step="0.5" value="${task.be}"></label></div><textarea data-cloze-field="instructions" placeholder="Erklärung und Arbeitsauftrag">${escapeHtml(task.instructions||"")}</textarea><label class="field-label cloze-author-field">Lückentext<textarea data-cloze-field="clozeText" placeholder="Die [[Erde]] kreist um die [[Sonne]].">${escapeHtml(task.clozeText||"")}</textarea><small>Markiere Lösungen mit [[…]]. Alternativen können mit | getrennt werden.</small></label><div class="cloze-preview" id="clozePreview"></div><div class="field-config cloze-field-config"><span></span><button id="removeTask" class="danger-link" type="button">Bereich löschen</button></div></article>`;const updatePreview=()=>{$("#clozePreview").innerHTML=parseClozeText(task.clozeText||"").map(part=>part.type==="gap"?`<span class="cloze-preview-gap">${escapeHtml(part.solutions[0]||"Lücke")}</span>`:escapeHtml(part.text)).join("")};host.querySelectorAll("[data-cloze-field]").forEach(input=>input.addEventListener("input",()=>{task[input.dataset.clozeField]=input.type==="number"?Math.max(0,Number(input.value)||0):input.value;persistProject();if(input.dataset.clozeField==="clozeText")updatePreview()}));$("#removeTask").onclick=()=>{if(project.tasks.length===1){toast("Mindestens ein Aufgabenbereich bleibt erhalten.");return}project.tasks=project.tasks.filter(entry=>entry.id!==task.id);activeTaskId=project.tasks[Math.max(0,index-1)].id;persistProject();renderTaskEditor()};updatePreview()};
function clozeWordBank(task){const automatic=parseClozeText(task.clozeText||"").filter(part=>part.type==="gap").map(part=>part.solutions[0]).filter(Boolean),extras=String(task.wordBankExtras||"").split(/[\n,;]/).map(value=>value.trim()).filter(Boolean);return[...new Set([...automatic,...extras])]}
const renderClozeTaskEditor=renderTaskEditor;
renderTaskEditor=function(){renderClozeTaskEditor();const task=project.tasks.find(entry=>entry.id===activeTaskId);if(task?.type!=="cloze")return;const preview=$("#clozePreview"),section=document.createElement("section");section.className="cloze-word-bank-editor";section.innerHTML=`<label class="cloze-word-bank-toggle"><input id="clozeWordBankEnabled" type="checkbox" ${task.wordBankEnabled?"checked":""}><span>Wortspeicher anzeigen</span></label><label class="field-label">Weitere Begriffe<textarea id="clozeWordBankExtras" placeholder="Zusätzliche Begriffe oder Ablenkungswörter, getrennt durch Komma oder Zeilenumbruch" ${task.wordBankEnabled?"":"disabled"}>${escapeHtml(task.wordBankExtras||"")}</textarea></label><div id="clozeWordBankPreview" class="cloze-word-bank"></div>`;preview.before(section);const enabled=$("#clozeWordBankEnabled"),extras=$("#clozeWordBankExtras"),bankPreview=$("#clozeWordBankPreview"),refresh=()=>{extras.disabled=!enabled.checked;bankPreview.hidden=!enabled.checked;bankPreview.innerHTML=clozeWordBank(task).map(word=>`<span>${escapeHtml(word)}</span>`).join("")};enabled.onchange=()=>{task.wordBankEnabled=enabled.checked;persistProject();refresh()};extras.oninput=()=>{task.wordBankExtras=extras.value;persistProject();refresh()};const clozeInput=document.querySelector('[data-cloze-field="clozeText"]');clozeInput?.addEventListener("input",refresh);refresh()};

function projectBe(entry){return entry.tasks.reduce((sum,task)=>sum+(Number(task.be)||0),0)}
function exportTeacherProject(entry){download(`${slug(entry.title)}.fokus-lehrer`,{type:"schola-fokus-teacher-project",version:1,exportedAt:new Date().toISOString(),project:structuredClone(entry)});toast("Lehrerversion exportiert.")}
function duplicateProject(entry){const copy=structuredClone(entry);copy.id=uid();copy.title=`${entry.title} – Kopie`;copy.unlockCode=makeCode();copy.codes=[];copy.tasks=copy.tasks.map(task=>({...task,id:uid()}));projects.push(copy);persistProject();renderProjectBrowser();toast("Projekt dupliziert.")}
function renderProjectBrowser(){const host=$("#focusProjectList");if(!host)return;host.innerHTML=projects.map(entry=>`<article class="focus-project-card ${entry.id===project.id?"is-active":""}" data-project-card="${entry.id}"><span class="eyebrow">${entry.id===project.id?"Aktuelles Projekt":"Lehrkraftprojekt"}</span><h2>${escapeHtml(entry.title||"Unbenanntes Projekt")}</h2><div class="focus-project-meta"><span>${entry.tasks.length} ${entry.tasks.length===1?"Aufgabe":"Aufgaben"}</span><span>${projectBe(entry)} BE</span><span>${entry.codes.length} Codes</span></div><div class="focus-project-card-actions"><button class="open-project" data-project-action="open">Im Editor öffnen</button><button data-project-action="export">Lehrerversion</button><button data-project-action="duplicate" title="Projekt duplizieren">Kopie</button><button class="delete-project" data-project-action="delete">Löschen</button></div></article>`).join("");host.querySelectorAll("[data-project-action]").forEach(button=>button.onclick=()=>{const card=button.closest("[data-project-card]"),entry=projects.find(item=>item.id===card.dataset.projectCard);if(!entry)return;const action=button.dataset.projectAction;if(action==="open")loadProjectIntoEditor(entry);if(action==="export")exportTeacherProject(entry);if(action==="duplicate")duplicateProject(entry);if(action==="delete"){if(!confirm(`Möchtest du „${entry.title}“ wirklich lokal löschen?`))return;if(projects.length===1){toast("Mindestens ein Projekt bleibt erhalten.");return}projects=projects.filter(item=>item.id!==entry.id);if(project.id===entry.id){project=projects[0];activeTaskId=project.tasks[0]?.id;$("#projectTitle").value=project.title;$("#projectIntro").value=project.intro;renderTeacherNav();renderTaskEditor()}persistProject();renderProjectBrowser()}})}
function deleteFocusProject(entry){if(!confirm(`Möchtest du „${entry.title}“ wirklich lokal löschen?`))return;if(projects.length===1){toast("Mindestens ein Projekt bleibt erhalten.");return}projects=projects.filter(item=>item.id!==entry.id);if(project.id===entry.id){project=projects[0];activeTaskId=project.tasks[0]?.id;$("#projectTitle").value=project.title;$("#projectIntro").value=project.intro;renderTeacherNav();renderTaskEditor()}persistProject();renderProjectBrowser()}
function selectBrowserProject(entry){project=entry;activeTaskId=project.tasks[0]?.id;$("#projectTitle").value=project.title;$("#projectIntro").value=project.intro;localStorage.setItem(STORAGE_PROJECTS,JSON.stringify({version:2,activeProjectId:project.id,projects}));localStorage.setItem(STORAGE_PROJECT,JSON.stringify(project));renderTeacherNav();renderTaskEditor();renderProjectBrowser()}
function renderProjectBrowserV2(){const list=$("#focusProjectList"),detail=$("#focusProjectDetail");if(!list||!detail)return;list.innerHTML=projects.map(entry=>`<article class="focus-browser-row ${entry.id===project.id?"is-active":""}" data-project-row="${entry.id}"><span class="folder-icon" aria-hidden="true"></span><button class="focus-project-main" type="button"><strong>${escapeHtml(entry.title||"Unbenanntes Projekt")}</strong><small>${entry.tasks.length} ${entry.tasks.length===1?"Aufgabe":"Aufgaben"} · ${projectBe(entry)} BE</small></button><div class="focus-row-menu"><button type="button" data-quick-action="export" title="Lehrerversion exportieren" aria-label="Lehrerversion von ${escapeHtml(entry.title)} exportieren">⇩</button><button type="button" data-quick-action="more" title="Projekt duplizieren" aria-label="${escapeHtml(entry.title)} duplizieren">⋯</button></div></article>`).join("");list.querySelectorAll("[data-project-row]").forEach(row=>{const entry=projects.find(item=>item.id===row.dataset.projectRow);row.querySelector(".focus-project-main").onclick=()=>selectBrowserProject(entry);row.querySelector('[data-quick-action="export"]').onclick=()=>exportTeacherProject(entry);row.querySelector('[data-quick-action="more"]').onclick=()=>duplicateProject(entry)});detail.innerHTML=`<div class="focus-detail-intro"><span class="eyebrow">Aktuelles Projekt</span><h3>${escapeHtml(project.title||"Unbenanntes Projekt")}</h3><p>${escapeHtml(project.intro||"Keine Einleitung hinterlegt.")}</p></div><div class="focus-detail-stats"><div><strong>${project.tasks.length}</strong><span>Aufgabenbereiche</span></div><div><strong>${projectBe(project)}</strong><span>Bewertungseinheiten</span></div><div><strong>${project.codes.length}</strong><span>Zugangscodes</span></div></div><div class="focus-detail-actions"><button type="button" data-detail-action="open">Im Editor öffnen</button><button type="button" data-detail-action="export">Lehrerversion exportieren</button><button type="button" data-detail-action="duplicate">Projekt duplizieren</button><button type="button" class="delete-project" data-detail-action="delete">Projekt löschen</button></div>`;detail.querySelector('[data-detail-action="open"]').onclick=()=>loadProjectIntoEditor(project);detail.querySelector('[data-detail-action="export"]').onclick=()=>exportTeacherProject(project);detail.querySelector('[data-detail-action="duplicate"]').onclick=()=>duplicateProject(project);detail.querySelector('[data-detail-action="delete"]').onclick=()=>deleteFocusProject(project)}
function removeFocusProject(entry){if(projects.length===1){toast("Mindestens ein Projekt bleibt erhalten.");return}projects=projects.filter(item=>item.id!==entry.id);if(project.id===entry.id){project=projects[0];activeTaskId=project.tasks[0]?.id;$("#projectTitle").value=project.title;$("#projectIntro").value=project.intro;renderTeacherNav();renderTaskEditor()}persistProject();renderProjectBrowser();toast("Projekt gelöscht.")}
function armProjectDelete(button,entry,pointerEvent){button.classList.add("is-arming");button.setPointerCapture?.(pointerEvent.pointerId);button._deleteTimer=setTimeout(()=>{button.classList.remove("is-arming");removeFocusProject(entry)},900)}
function cancelProjectDelete(button){clearTimeout(button._deleteTimer);button.classList.remove("is-arming")}
function renderProjectBrowserV3(){const list=$("#focusProjectList"),detail=$("#focusProjectDetail");if(!list||!detail)return;list.innerHTML=projects.map(entry=>`<article class="focus-browser-row ${entry.id===project.id?"is-active":""}" data-project-row="${entry.id}"><span class="folder-icon" aria-hidden="true"></span><button class="focus-project-main" type="button"><strong>${escapeHtml(entry.title||"Unbenanntes Projekt")}</strong><small>${entry.tasks.length} ${entry.tasks.length===1?"Aufgabe":"Aufgaben"} · ${projectBe(entry)} BE</small></button><div class="focus-project-menu-shell"><button class="focus-project-menu-button" type="button" aria-label="Menü für ${escapeHtml(entry.title)}" aria-expanded="false"><span class="browser-actions-dots" aria-hidden="true"></span></button><div class="focus-project-menu" hidden><button type="button" data-menu-action="export">Lehrerversion exportieren</button><button type="button" data-menu-action="duplicate">Projekt duplizieren</button><button type="button" class="delete-project" data-menu-action="delete" title="Zum Löschen gedrückt halten">Projekt löschen</button></div></div></article>`).join("");list.querySelectorAll("[data-project-row]").forEach(row=>{const entry=projects.find(item=>item.id===row.dataset.projectRow),menuButton=row.querySelector(".focus-project-menu-button"),menu=row.querySelector(".focus-project-menu");row.querySelector(".focus-project-main").onclick=()=>selectBrowserProject(entry);menuButton.onclick=event=>{event.stopPropagation();list.querySelectorAll(".focus-project-menu").forEach(other=>{if(other!==menu)other.hidden=true});list.querySelectorAll(".focus-project-menu-button").forEach(other=>{if(other!==menuButton)other.setAttribute("aria-expanded","false")});menu.hidden=!menu.hidden;menuButton.setAttribute("aria-expanded",String(!menu.hidden))};menu.querySelector('[data-menu-action="export"]').onclick=()=>{exportTeacherProject(entry);menu.hidden=true};menu.querySelector('[data-menu-action="duplicate"]').onclick=()=>{duplicateProject(entry);menu.hidden=true};const deleteButton=menu.querySelector('[data-menu-action="delete"]');deleteButton.onpointerdown=event=>{event.preventDefault();armProjectDelete(deleteButton,entry,event)};deleteButton.onpointerup=()=>cancelProjectDelete(deleteButton);deleteButton.onpointercancel=()=>cancelProjectDelete(deleteButton);deleteButton.onpointerleave=()=>cancelProjectDelete(deleteButton);deleteButton.onclick=event=>event.preventDefault()});detail.innerHTML=`<div class="focus-detail-intro"><span class="eyebrow">Aktuelles Projekt</span><h3>${escapeHtml(project.title||"Unbenanntes Projekt")}</h3><p>${escapeHtml(project.intro||"Keine Einleitung hinterlegt.")}</p></div><div class="focus-detail-stats"><div><strong>${project.tasks.length}</strong><span>Aufgabenbereiche</span></div><div><strong>${projectBe(project)}</strong><span>Bewertungseinheiten</span></div><div><strong>${project.codes.length}</strong><span>Zugangscodes</span></div></div><div class="focus-detail-actions"><button type="button" data-detail-action="open">Im Editor öffnen</button></div>`;detail.querySelector('[data-detail-action="open"]').onclick=()=>loadProjectIntoEditor(project)}
const FOCUS_DELETE_HOLD_MS=820;
let focusDeleteHoldState=null;
function resetFocusDeleteHold(){if(!focusDeleteHoldState)return;const{button,frame,pointerId}=focusDeleteHoldState;if(frame)cancelAnimationFrame(frame);button.classList.remove("is-hold-active","is-hold-ready");button.style.removeProperty("--hold-progress");if(Number.isFinite(pointerId)&&button.hasPointerCapture?.(pointerId)){try{button.releasePointerCapture(pointerId)}catch{}}focusDeleteHoldState=null}
function tickFocusDeleteHold(){if(!focusDeleteHoldState)return;const progress=Math.max(0,Math.min(1,(performance.now()-focusDeleteHoldState.startedAt)/FOCUS_DELETE_HOLD_MS));focusDeleteHoldState.button.style.setProperty("--hold-progress",`${progress*100}%`);if(progress>=1){focusDeleteHoldState.armed=true;focusDeleteHoldState.button.classList.add("is-hold-ready");focusDeleteHoldState.frame=null;return}focusDeleteHoldState.frame=requestAnimationFrame(tickFocusDeleteHold)}
function beginFocusDeleteHold(event){const button=event.currentTarget;if(!(button instanceof HTMLButtonElement))return;event.preventDefault();event.stopPropagation();resetFocusDeleteHold();focusDeleteHoldState={button,projectId:button.dataset.projectId,pointerId:Number.isFinite(event.pointerId)?event.pointerId:null,startedAt:performance.now(),armed:false,frame:null};button.setPointerCapture?.(event.pointerId);button.classList.add("is-hold-active");button.style.setProperty("--hold-progress","0%");focusDeleteHoldState.frame=requestAnimationFrame(tickFocusDeleteHold)}
function finishFocusDeleteHold(event){if(!focusDeleteHoldState)return;event.preventDefault();event.stopPropagation();const{button,projectId,armed}=focusDeleteHoldState;const releaseTarget=document.elementFromPoint(event.clientX,event.clientY);const releasedOnButton=Boolean(releaseTarget&&(releaseTarget===button||button.contains(releaseTarget)));resetFocusDeleteHold();if(!armed||!releasedOnButton)return;const entry=projects.find(item=>item.id===projectId);if(entry)removeFocusProject(entry)}
function cancelFocusDeleteHold(event){if(!focusDeleteHoldState)return;event.preventDefault();event.stopPropagation();resetFocusDeleteHold()}
function closeFocusProjectMenus(exceptShell=null){document.querySelectorAll(".schedule-menu-shell").forEach(shell=>{if(shell===exceptShell)return;const menu=shell.querySelector(".schedule-menu"),button=shell.querySelector(".schedule-menu-button");if(menu)menu.hidden=true;button?.setAttribute("aria-expanded","false")})}
