function focusSubmissionStatusLabel(value){return value==="absent"?"Nicht anwesend":value==="handwritten"?"Handschriftlich abgegeben":value==="submitted"?"Arbeitsdatei importiert":"Keine Angabe"}
function renderFocusStudentDetail(detail){const{classEntry,student}=getActiveFocusStudent();if(!classEntry||!student){activeFocusBrowserNode={type:"classes",projectId:project.id,classId:null};renderFocusClassesDetail(detail);return}const submission=student.submission||null,status=student.submissionStatus||"pending";detail.innerHTML=`<div class="focus-detail-intro"><span class="eyebrow">${escapeHtml(classEntry.name)}</span><h3>${escapeHtml(student.fullName||"Unbenannter Schüler")}</h3><p>Hier wird die fertige Arbeit dieses Schülers lokal gesammelt.</p></div><div class="focus-student-submission-editor"><label class="field-label">Abgabestatus<select id="focusStudentSubmissionStatus"><option value="pending" ${status==="pending"?"selected":""}>Keine Angabe</option><option value="absent" ${status==="absent"?"selected":""}>Nicht anwesend</option><option value="handwritten" ${status==="handwritten"?"selected":""}>Handschriftlich abgegeben</option><option value="submitted" ${status==="submitted"?"selected":""} ${submission?"":"disabled"}>Arbeitsdatei importiert</option></select></label><div class="focus-submission-card ${submission?"has-submission":""}">${submission?`<span class="eyebrow">Importierte Arbeit</span><strong>${escapeHtml(submission.fileName)}</strong><small>${escapeHtml(new Date(submission.importedAt).toLocaleString("de-DE"))} · ${submission.result.answers?.length||0} Aufgaben</small>`:'<p>Noch keine Arbeitsdatei importiert.</p>'}</div><label class="file-button secondary focus-submission-import">Arbeitsdatei importieren<input id="focusStudentResultImport" type="file" accept=".fokus-resultat,application/json"></label><p id="focusStudentImportError" class="error" role="alert"></p></div>`;$("#focusStudentSubmissionStatus").onchange=event=>{student.submissionStatus=event.target.value;saveFocusLibrarySilently();toast(`Status: ${focusSubmissionStatusLabel(student.submissionStatus)}`)};$("#focusStudentResultImport").onchange=async event=>{const file=event.target.files[0];if(!file)return;try{const result=await readJsonFile(file);if(result?.type!=="schola-fokus-result")throw new Error("Diese Datei ist keine gültige Fokus-Arbeitsdatei.");if(result.projectId&&result.projectId!==project.id)throw new Error("Diese Arbeit gehört zu einem anderen Fokus-Projekt.");student.submission={fileName:file.name,importedAt:new Date().toISOString(),result};student.submissionStatus="submitted";persistProject();renderProjectBrowser();toast("Arbeitsdatei dem Schüler zugeordnet.")}catch(error){$("#focusStudentImportError").textContent=error.message;event.target.value=""}}}
$("#cancelClassLink").onclick=()=>$("#classLinkDialog").close();
$("#cancelClassLinkAction").onclick=()=>$("#classLinkDialog").close();
$("#classLinkForm").onsubmit=event=>{event.preventDefault();try{linkFocusClassById(project,$("#classLinkId").value);$("#classLinkDialog").close()}catch(error){$("#classLinkError").textContent=error.message}};
$("#focusBrowserActions").onclick=event=>{event.stopPropagation();const menu=$("#focusBrowserMenu"),open=menu.hidden;menu.hidden=!open;$("#focusBrowserActions").setAttribute("aria-expanded",String(open))};
document.addEventListener("click",event=>{if(!event.target.closest(".browser-actions-menu-shell")){$("#focusBrowserMenu").hidden=true;$("#focusBrowserActions").setAttribute("aria-expanded","false")}if(!event.target.closest(".schedule-menu-shell"))closeFocusProjectMenus()});
$("#newFocusProject").onclick=()=>{$("#focusBrowserMenu").hidden=true;const next=initialProject();projects.push(next);loadProjectIntoEditor(next);toast("Neues Fokus-Projekt angelegt.")};
$("#teacherProjectImport").onchange=async event=>{try{const data=await readJsonFile(event.target.files[0]);if(data?.type!=="schola-fokus-teacher-project"||data.version!==1||!data.project||!Array.isArray(data.project.tasks))throw new Error("Diese Datei ist keine gültige Fokus-Lehrerversion.");const imported=structuredClone(data.project);if(projects.some(entry=>entry.id===imported.id))imported.id=uid();imported.unlockCode=normalizeCode(imported.unlockCode)||makeCode();imported.codes=Array.isArray(imported.codes)?imported.codes:[];imported.tasks=imported.tasks.length?imported.tasks.map(task=>({...task,type:task.type||"text"})):[{id:uid(),type:"text",title:"Aufgabe 1",instructions:"",be:5,wordLimit:0}];projects.push(imported);event.target.value="";loadProjectIntoEditor(imported);toast("Lehrerversion importiert.")}catch(error){toast(error.message)}};

function renderCodes(){const host=$("#codeList");host.innerHTML=project.codes.length?project.codes.map((entry,index)=>`<label class="code-entry ${entry.used?"is-used":""}"><input type="checkbox" data-code-index="${index}" ${entry.used?"checked":""}><code>${entry.value}</code></label>`).join(""):'<p>Noch keine Codes erzeugt.</p>';host.querySelectorAll("input").forEach(input=>input.onchange=()=>{project.codes[Number(input.dataset.codeIndex)].used=input.checked;persistProject();renderCodes()})}
$("#showCodes").onclick=()=>{$("#teacherUnlockCode").textContent=project.unlockCode;renderCodes();$("#codesDialog").showModal()};
$("#generateCodes").onclick=()=>{const count=Math.min(100,Math.max(1,Number($("#codeCount").value)||12));const validCodes=project.codes.filter(entry=>normalizeCode(entry.value).length===4);if(validCodes.length!==project.codes.length)project.codes=validCodes;const existing=new Set(project.codes.map(c=>c.value));while(project.codes.length<count){const value=makeCode();if(!existing.has(value)){existing.add(value);project.codes.push({value,used:false})}}persistProject();renderCodes()};
$("#copyCodes").onclick=async()=>{const text=project.codes.filter(c=>!c.used).map(c=>c.value).join("\n");try{await navigator.clipboard.writeText(text);toast("Verfügbare Codes kopiert.")}catch{toast("Kopieren war nicht möglich.")}};

async function buildPackage(){const codeHashes=await Promise.all(project.codes.map(c=>digest(c.value))),unlockHash=await digest(project.unlockCode),tasks=project.tasks.map(({id,type="text",title,instructions,be,wordLimit,clozeText,wordBankEnabled,wordBankExtras})=>{if(type!=="cloze")return{id,type,title,instructions,be,wordLimit};const teacherTask={clozeText,wordBankExtras},parts=parseClozeText(clozeText||"");return{id,type,title,instructions,be,clozeText:parts.map(part=>part.type==="text"?part.text:"[[]]").join(""),wordBank:wordBankEnabled?clozeWordBank(teacherTask):[]}});return{type:"schola-fokus-package",version:1,id:project.id,title:project.title,intro:project.intro,createdAt:new Date().toISOString(),codeHashes,unlockHash,tasks}}
$("#exportProject").onclick=async()=>{if(!project.codes.length){toast("Erzeuge zuerst mindestens einen Zugangscode.");$("#showCodes").click();return}download(`${slug(project.title)}.fokus`,await buildPackage());toast("Schülerversion exportiert.")};
$("#previewProject").onclick=async()=>{teacherPreviewMode=true;studentPackage=await buildPackage();session=null;renderStudentPackage();setMode("student")};

async function readJsonFile(file){if(!file)return null;try{return JSON.parse(await file.text())}catch{throw new Error("Die Datei enthält kein gültiges Fokus-Format.")}}
$("#studentImport").onchange=async e=>{try{const data=await readJsonFile(e.target.files[0]);if(data?.type!=="schola-fokus-package"||data.version!==1)throw new Error("Diese Datei ist kein gültiger Fokus-Aufgabenspace.");teacherPreviewMode=false;studentPackage=data;session=null;localStorage.removeItem(STORAGE_SESSION);renderStudentPackage()}catch(error){toast(error.message)}};

function renderStudentPackage(){if(!studentPackage)return;$("#studentLanding").hidden=true;$("#studentProject").hidden=false;$("#studentTitle").textContent=studentPackage.title;$("#studentIntro").textContent=studentPackage.intro||"";const answers=session?.answers||{};$("#studentTasks").innerHTML=studentPackage.tasks.map((task,index)=>`<article class="student-task"><header><div><span class="eyebrow">Aufgabe ${index+1}</span><h2>${escapeHtml(task.title)}</h2></div><strong>${Number(task.be)||0} BE</strong></header><p class="instruction">${escapeHtml(task.instructions)}</p><textarea class="student-answer" data-answer="${task.id}" data-limit="${Number(task.wordLimit)||0}" placeholder="Deine Antwort …" disabled>${escapeHtml(answers[task.id]||"")}</textarea><div class="word-counter" data-counter="${task.id}">${task.wordLimit?`0 / ${task.wordLimit} Wörter`:"0 Wörter"}</div></article>`).join("");$$('.student-answer').forEach(area=>{autoGrow(area);updateCount(area);area.addEventListener("input",()=>handleAnswerInput(area));area.addEventListener("paste",blockTransfer);area.addEventListener("drop",blockTransfer);area.addEventListener("cut",blockTransfer)});$("#startSession").hidden=false;$("#finishSession").hidden=true;$("#endTeacherPreview").hidden=true;$("#sessionLabel").textContent="Noch nicht gestartet"}
const renderTextStudentPackage=renderStudentPackage;
function renderStudentClozeParts(task,saved){let gapIndex=0;return parseClozeText(task.clozeText||"").map(part=>{if(part.type==="text")return escapeHtml(part.text);const index=gapIndex++;return`<input class="student-cloze-input" data-cloze-answer="${task.id}" data-gap-index="${index}" value="${escapeHtml(saved[index]||"")}" aria-label="Lücke ${index+1}" disabled>`}).join("")}
renderStudentPackage=function(){renderTextStudentPackage();const answers=session?.answers||{};studentPackage.tasks.forEach((task,taskIndex)=>{if(task.type!=="cloze")return;const article=$("#studentTasks").children[taskIndex],saved=String(answers[task.id]||"").split("␟");article.innerHTML=`<header><div><span class="eyebrow">Aufgabe ${taskIndex+1}</span><h2>${escapeHtml(task.title)}</h2></div><strong>${Number(task.be)||0} BE</strong></header><p class="instruction">${escapeHtml(task.instructions||"")}</p><div class="student-cloze-text" data-cloze-task="${task.id}">${renderStudentClozeParts(task,saved)}</div>`});$$('.student-cloze-input').forEach(input=>{input.addEventListener("input",()=>{const taskId=input.dataset.clozeAnswer,values=[...document.querySelectorAll(`[data-cloze-answer="${taskId}"]`)].map(field=>field.value);session.answers[taskId]=values.join("␟");persistSession()});input.addEventListener("paste",blockTransfer);input.addEventListener("drop",blockTransfer);input.addEventListener("cut",blockTransfer)})};
const renderClozeStudentPackage=renderStudentPackage;
renderStudentPackage=function(){renderClozeStudentPackage();studentPackage.tasks.forEach((task,index)=>{if(task.type!=="cloze"||!task.wordBank?.length)return;const text=$("#studentTasks").children[index]?.querySelector(".student-cloze-text");if(!text)return;const bank=document.createElement("div");bank.className="student-cloze-word-bank";bank.innerHTML=`<span class="eyebrow">Wortspeicher</span><div class="cloze-word-bank">${task.wordBank.map(word=>`<span>${escapeHtml(word)}</span>`).join("")}</div>`;text.before(bank)})};
function focusTaskTypeLabel(type){return({text:"Textaufgabe",cloze:"Lückentext"})[type]||"Aufgabenbereich"}
const renderTypedStudentPackage=renderStudentPackage;
renderStudentPackage=function(){renderTypedStudentPackage();studentPackage.tasks.forEach((task,index)=>{const eyebrow=$("#studentTasks").children[index]?.querySelector("header .eyebrow");if(eyebrow)eyebrow.textContent=focusTaskTypeLabel(task.type||"text")})};
function words(value){return String(value).trim()?String(value).trim().split(/\s+/):[]}
function autoGrow(area){area.style.height="auto";area.style.height=`${Math.max(180,area.scrollHeight+2)}px`}
function updateCount(area){const count=words(area.value).length,limit=Number(area.dataset.limit)||0,counter=document.querySelector(`[data-counter="${area.dataset.answer}"]`);counter.textContent=limit?`${count} / ${limit} Wörter`:`${count} Wörter`;counter.classList.toggle("is-over",Boolean(limit&&count>limit))}
function handleAnswerInput(area){const limit=Number(area.dataset.limit)||0;let list=words(area.value);if(limit&&list.length>limit){area.value=list.slice(0,limit).join(" ");logEvent("word-limit-reached",{taskId:area.dataset.answer,limit})}session.answers[area.dataset.answer]=area.value;updateCount(area);autoGrow(area);persistSession()}
function blockTransfer(event){if(!session||session.state!=="active")return;event.preventDefault();logEvent(`${event.type}-attempt`,{taskId:event.target.dataset.answer});toast("Einfügen, Ausschneiden und Ablegen sind während der Bearbeitung gesperrt.")}
function logEvent(type,details={}){if(!session)return;session.events.push({type,at:new Date().toISOString(),...details});persistSession()}

function startTeacherPreviewSession(){session={type:"schola-fokus-session",version:1,package:studentPackage,code:"",codeHash:"",state:"active",startedAt:new Date().toISOString(),lockedAt:null,answers:{},events:[{type:"teacher-preview-started",at:new Date().toISOString()}]};persistSession();activateSession();requestFullscreen()}
$("#startSession").onclick=()=>teacherPreviewMode?startTeacherPreviewSession():$("#startDialog").showModal();$("#cancelStart").onclick=()=>$("#startDialog").close();
$("#startForm").onsubmit=async event=>{event.preventDefault();const code=$("#studentCode").value,hash=await digest(code);if(studentPackage.codeHashes.length&&!studentPackage.codeHashes.includes(hash)){$("#codeError").textContent="Dieser Code gehört nicht zu diesem Aufgabenspace.";return}$("#codeError").textContent="";session={type:"schola-fokus-session",version:1,package:studentPackage,code:normalizeCode(code),codeHash:hash,state:"active",startedAt:new Date().toISOString(),lockedAt:null,answers:{},events:[{type:"session-started",at:new Date().toISOString()}]};persistSession();$("#startDialog").close();activateSession();requestFullscreen()};
function activateSession(){session.state="active";persistSession();document.body.classList.add("session-active");$("#startSession").hidden=true;$("#finishSession").hidden=false;$("#endTeacherPreview").hidden=!teacherPreviewMode;$("#sessionLabel").textContent="Bearbeitung läuft";$$('.student-answer,.student-cloze-input').forEach(a=>a.disabled=false);$("#lockScreen").hidden=true;startClock()}
function resumeSession(){if(session.state==="locked"){showLock();return}activateSession()}
function requestFullscreen(){document.documentElement.requestFullscreen?.().catch(()=>logEvent("fullscreen-denied"))}
function startClock(){clearInterval(clockTimer);const tick=()=>{const seconds=Math.max(0,Math.floor((Date.now()-new Date(session.startedAt).getTime())/1000));$("#sessionClock").textContent=`${String(Math.floor(seconds/60)).padStart(2,"0")}:${String(seconds%60).padStart(2,"0")}`};tick();clockTimer=setInterval(tick,1000)}

function focusLost(reason){if(!session||session.state!=="active"||lostFocusAt)return;lostFocusAt=Date.now();logEvent("focus-lost",{reason});clearInterval(warningTimer);let last=10;$("#warningSeconds").textContent=last;$("#focusWarning").hidden=false;warningTimer=setInterval(()=>{const elapsed=Math.floor((Date.now()-lostFocusAt)/1000),remaining=Math.max(0,10-elapsed);if(remaining!==last){last=remaining;$("#warningSeconds").textContent=remaining}if(elapsed>=10)lockSession(reason)},250)}
function focusReturned(){if(!lostFocusAt||!session||session.state!=="active")return;const elapsed=Date.now()-lostFocusAt;if(elapsed>=10000){lockSession("focus-timeout");return}logEvent("focus-restored",{absenceMilliseconds:elapsed});lostFocusAt=null;clearInterval(warningTimer);$("#focusWarning").hidden=true}
function lockSession(reason){if(!session||session.state!=="active")return;session.state="locked";session.lockedAt=new Date().toISOString();logEvent("session-locked",{reason,absenceMilliseconds:lostFocusAt?Date.now()-lostFocusAt:null});lostFocusAt=null;clearInterval(warningTimer);$("#focusWarning").hidden=true;showLock()}
function showLock(){const isLocalTeacherProject=Boolean(session?.package?.id&&project?.id===session.package.id);$("#recoverTeacherPreview").hidden=!isLocalTeacherProject;$("#lockScreen").hidden=false;$$('.student-answer').forEach(a=>a.disabled=true);$("#sessionLabel").textContent="Gesperrt"}
document.addEventListener("visibilitychange",()=>document.hidden?focusLost("document-hidden"):focusReturned());window.addEventListener("blur",()=>focusLost("window-blur"));window.addEventListener("focus",focusReturned);window.addEventListener("pagehide",()=>{if(session?.state==="active")lockSession("page-left")});document.addEventListener("fullscreenchange",()=>{if(session?.state==="active"&&!document.fullscreenElement)focusLost("fullscreen-exited")});document.addEventListener("keydown",event=>{if(session?.state!=="active")return;if((event.ctrlKey||event.metaKey)&&["v","x"].includes(event.key.toLowerCase())){event.preventDefault();logEvent("shortcut-blocked",{key:event.key.toLowerCase()})}});
$("#unlockSession").onclick=async()=>{const candidate=await digest($("#unlockCode").value);if(candidate!==studentPackage.unlockHash){$("#unlockError").textContent="Entsperrcode nicht korrekt.";return}$("#unlockError").textContent="";logEvent("session-unlocked");activateSession();requestFullscreen()};
$("#leaveLockedSession").onclick=()=>{if(!session||session.state!=="locked")return;if(!confirm("Möchtest du diese gesperrte Bearbeitung verlassen? Der lokale Zwischenstand dieser Arbeit wird verworfen."))return;clearInterval(clockTimer);clearInterval(warningTimer);lostFocusAt=null;localStorage.removeItem(STORAGE_SESSION);session=null;studentPackage=null;document.body.classList.remove("session-active");$("#lockScreen").hidden=true;$("#studentProject").hidden=true;$("#studentLanding").hidden=false;$("#studentImport").value="";document.exitFullscreen?.();setMode("student");toast("Gesperrte Bearbeitung verlassen.")};
function endTeacherPreview(){if(!teacherPreviewMode||!session?.package?.id||project?.id!==session.package.id)return;clearInterval(clockTimer);clearInterval(warningTimer);lostFocusAt=null;localStorage.removeItem(STORAGE_SESSION);session=null;studentPackage=null;teacherPreviewMode=false;document.body.classList.remove("session-active");$("#lockScreen").hidden=true;$("#endTeacherPreview").hidden=true;document.exitFullscreen?.();setMode("teacher");toast("Lehrkraft-Vorschau beendet.")}
$("#recoverTeacherPreview").onclick=endTeacherPreview;
$("#endTeacherPreview").onclick=endTeacherPreview;
$("#finishSession").onclick=()=>{if(!session||session.state!=="active")return;$("#studentFullName").value="";$("#nameError").textContent="";$("#finishDialog").showModal();$("#studentFullName").focus()};
$("#cancelFinish").onclick=()=>$("#finishDialog").close();
$("#finishForm").onsubmit=event=>{event.preventDefault();if(!session||session.state!=="active")return;const studentName=$("#studentFullName").value.trim().replace(/\s+/g," ");if(studentName.length<3||!studentName.includes(" ")){$("#nameError").textContent="Bitte gib deinen vollständigen Vor- und Nachnamen ein.";return}const finishedDate=new Date();session.studentName=studentName;session.state="finished";session.finishedAt=finishedDate.toISOString();logEvent("session-finished");clearInterval(clockTimer);clearInterval(warningTimer);lostFocusAt=null;const payload={type:"schola-fokus-result",version:1,studentName,projectId:studentPackage.id,title:studentPackage.title,code:session.code,startedAt:session.startedAt,finishedAt:session.finishedAt,answers:studentPackage.tasks.map(task=>({taskId:task.id,title:task.title,be:task.be,wordLimit:task.wordLimit,text:session.answers[task.id]||"",wordCount:words(session.answers[task.id]||"").length})),integrity:{events:session.events}};download(`${filenamePart(studentName)}_${filenameTimestamp(finishedDate)}_${slug(studentPackage.title)}.fokus-resultat`,payload);$("#finishDialog").close();$$('.student-answer').forEach(a=>a.disabled=true);$("#finishSession").hidden=true;$("#sessionLabel").textContent="Abgegeben";document.body.classList.remove("session-active");document.exitFullscreen?.();localStorage.removeItem(STORAGE_SESSION);toast("Ergebnisdatei wurde exportiert.")};

const finishFocusFormHandler=$("#finishForm").onsubmit;
$("#finishForm").onsubmit=event=>{finishFocusFormHandler(event);if(session?.state==="finished")$$('.student-cloze-input').forEach(input=>input.disabled=true)};
$("#resultImport").onchange=async event=>{try{const data=await readJsonFile(event.target.files[0]);if(data?.type!=="schola-fokus-result")throw new Error("Keine gültige Fokus-Ergebnisdatei.");const code=normalizeCode(data.code);const match=project.codes.find(entry=>normalizeCode(entry.value)===code);if(match){match.used=true;persistProject();renderCodes();toast(`Code ${match.value} als verwendet markiert.`)}else toast("Der Ergebniscode gehört nicht zur aktuellen Codeliste.")}catch(error){toast(error.message)}};

renderTeacherNav();renderTaskEditor();if(session?.package){studentPackage=session.package}setMode("student")

const focusMenuButton=$("#menuButton"),focusMenuClose=$("#menuCloseButton"),focusSideMenu=$("#sideMenu"),focusMenuOverlay=$("#menuOverlay");
function setFocusMenuOpen(open){focusSideMenu.classList.toggle("is-open",open);focusSideMenu.setAttribute("aria-hidden",String(!open));focusMenuButton.setAttribute("aria-expanded",String(open));focusMenuOverlay.hidden=!open;if(open)focusSideMenu.removeAttribute("inert");else focusSideMenu.setAttribute("inert","")}
focusMenuButton.onclick=()=>setFocusMenuOpen(focusMenuButton.getAttribute("aria-expanded")!=="true");
focusMenuClose.onclick=()=>setFocusMenuOpen(false);
focusMenuOverlay.onclick=()=>setFocusMenuOpen(false);
document.addEventListener("keydown",event=>{if(event.key==="Escape"&&focusSideMenu.classList.contains("is-open"))setFocusMenuOpen(false)});
